add_action( 'woocommerce_before_checkout_billing_form', 'perfectpixel_country_message_box' );
add_action( 'woocommerce_after_checkout_form', 'perfectpixel_country_message_script' );

function perfectpixel_country_message_box() {
	echo '<div id="perfectpixel-country-message" class="woocommerce-info" style="display:none">' . esc_html( '{{country_message}}' ) . '</div>';
}

function perfectpixel_country_message_script() {
	$countries = array_filter( array_map( 'trim', explode( ',', strtoupper( '{{message_countries}}' ) ) ) );
	?>
	<script>
	jQuery( function ( $ ) {
		var countries = <?php echo wp_json_encode( array_values( $countries ) ); ?>;
		var update = function () {
			$( '#perfectpixel-country-message' ).toggle( countries.indexOf( $( '#billing_country' ).val() ) !== -1 );
		};
		$( document.body ).on( 'change', '#billing_country', update );
		update();
	} );
	</script>
	<?php
}
